#!/usr/bin/env python3
"""Fail-closed second pass for Labline model-economy calibration."""
from __future__ import annotations
import base64, json, sys, zlib
from pathlib import Path
PAYLOAD = ""
class PatchError(RuntimeError): pass

def main() -> int:
    root=Path(sys.argv[1] if len(sys.argv)>1 else ".").resolve()
    data=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    try:
        for rel,old,new in data["replacements"]:
            p=root/rel
            if not p.is_file(): raise PatchError(f"Missing target file: {rel}")
            text=p.read_text(encoding="utf-8")
            count=text.count(old)
            if count!=1: raise PatchError(f"Expected one anchor in {rel}, found {count}")
            p.write_text(text.replace(old,new,1),encoding="utf-8")
        for rel,content in data["new_files"]:
            p=root/rel
            if p.exists(): raise PatchError(f"Refusing to overwrite: {rel}")
            p.parent.mkdir(parents=True,exist_ok=True)
            p.write_text(content,encoding="utf-8")
    except PatchError as exc:
        print(f"error: {exc}",file=sys.stderr); return 1
    print(f"Applied {len(data['replacements'])} economy replacements and created {len(data['new_files'])} tests.")
    return 0
if __name__=="__main__": raise SystemExit(main())
